    }

    cout << "Loans:\n";
    for (const Loan& l : loans) {
        l.display();
    }
    cout << "Copies left: book " << book.copies() << ", magazine " << magazine.copies() << ", dvd " << dvd.copies() << '\n';

    LibraryItem& any = dvd;
    cout << "Through a LibraryItem reference: ";
    any.describe();
    cout << '\n';
    return 0;
}
